    // clang-format on

    // Init itemNameToEnum
    for (auto& item : itemTable) {
        // Easiest way to filter out all the empty values from the array, since we still technically want the 0/RG_NONE
        // entry
        if (item.GetName().english.empty()) {
            continue;
        }
        // Getters fall back to English for missing translations, matching what the spoiler log writes
        itemNameToEnum[item.GetName().GetEnglish()] = item.GetRandomizerGet();
        itemNameToEnum[item.GetName().GetFrench()] = item.GetRandomizerGet();
        itemNameToEnum[item.GetName().GetGerman()] = item.GetRandomizerGet();
    }
